package com.eventmgr.web;
import com.eventmgr.util.*;import com.google.gson.JsonObject;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.util.*;
@WebServlet("/api/attendee/*") public class AttendeeServlet extends ApiServlet {
 protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{User u=me(q);String[] s=segs(q);String k=s.length>0?s[0]:"";if(k.equals("events"))send(r,200,Db.query("SELECT e.id,e.title,e.description,e.event_date,e.event_time,e.venue,e.category,u.name organizer_name,t.id ticket_id,t.name ticket_name,t.price,t.quantity,(SELECT COUNT(*) FROM registrations z WHERE z.ticket_id=t.id AND z.status<>'CANCELLED') sold FROM events e JOIN users u ON u.id=e.organizer_id JOIN tickets t ON t.event_id=e.id WHERE e.status='APPROVED' ORDER BY e.event_date,t.price"));else if(k.equals("registrations"))send(r,200,Db.query("SELECT r.id,r.status,r.quantity,r.total,r.created_at,e.title,e.event_date,e.event_time,e.venue,t.name ticket_name FROM registrations r JOIN events e ON e.id=r.event_id JOIN tickets t ON t.id=r.ticket_id WHERE r.attendee_id=? ORDER BY e.event_date DESC",u.id));else if(k.equals("updates"))send(r,200,Db.query("SELECT a.id,a.body,a.created_at,e.title,e.event_date,u.name organizer_name FROM announcements a JOIN events e ON e.id=a.event_id JOIN users u ON u.id=a.organizer_id JOIN registrations r ON r.event_id=e.id WHERE r.attendee_id=? AND r.status<>'CANCELLED' ORDER BY a.created_at DESC",u.id));else if(k.equals("profile"))send(r,200,Map.of("name",u.name,"email",u.email));else throw new ApiError(404,"Not found");}
 protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException{String[] s=segs(q);User u=me(q);if(s.length==1&&s[0].equals("registrations")){JsonObject b=body(q);long eid=(long)num(b,"eventId",1,Long.MAX_VALUE),tid=(long)num(b,"ticketId",1,Long.MAX_VALUE);Map<String,Object> t=Db.one("SELECT t.price,t.quantity,(SELECT COUNT(*) FROM registrations r WHERE r.ticket_id=t.id AND r.status<>'CANCELLED') sold,e.status,e.title FROM tickets t JOIN events e ON e.id=t.event_id WHERE t.id=? AND e.id=?",tid,eid);if(t==null||!"APPROVED".equals(t.get("status")))throw new ApiError(404,"Event or ticket not found");if(((Number)t.get("sold")).intValue()>=((Number)t.get("quantity")).intValue())throw new ApiError(409,"This ticket type is sold out");Db.insert("INSERT INTO registrations(event_id,ticket_id,attendee_id,quantity,total) VALUES(?,?,?,1,?)",eid,tid,u.id,t.get("price"));Activity.log(u.id,"Ticket reserved",(String)t.get("title")+" · "+t.get("price"));message(r,201,"Registration confirmed. Your ticket is ready.");return;}throw new ApiError(404,"Not found");}
 protected void doPut(HttpServletRequest q,HttpServletResponse r)throws IOException{String[] s=segs(q);User u=me(q);if(s.length==1&&s[0].equals("profile")){JsonObject b=body(q);String n=str(b,"name",true);if(n.length()>100)throw new ApiError(400,"Name is too long");Db.update("UPDATE users SET name=? WHERE id=?",n,u.id);u.name=n;Activity.log(u.id,"Profile updated",n+" updated their attendee profile");message(r,200,"Profile updated");return;}throw new ApiError(404,"Not found");}
 protected void doDelete(HttpServletRequest q,HttpServletResponse r)throws IOException{String[] s=segs(q);User u=me(q);if(s.length==2&&s[0].equals("registrations")){long rid=id(s[1]);Map<String,Object> ticket=Db.one("SELECT e.title FROM registrations r JOIN events e ON e.id=r.event_id WHERE r.id=? AND r.attendee_id=? AND r.status='CONFIRMED'",rid,u.id);if(ticket==null)throw new ApiError(404,"Active ticket not found");Db.update("UPDATE registrations SET status='CANCELLED' WHERE id=? AND attendee_id=? AND status='CONFIRMED'",rid,u.id);Activity.log(u.id,"Ticket cancelled",(String)ticket.get("title"));message(r,200,"Registration cancelled");return;}throw new ApiError(404,"Not found");}}
